# Two triangles in each partner cell, with shared numeric fill across states and directions.
tri<-list();kk<-0L;for(i in seq_len(nrow(net))){r<-net[i];xx<-match(r$partner,partners);for(state in c('high','low')){kk<-kk+1L;tri[[kk]]<-data.table(partner=r$partner,direction=r$direction,state=state,id=kk,x=xx+c(-.45,.45,if(state=='high')-.45 else .45),y=if(state=='high')c(.45,.45,-.45)else c(-.45,-.45,.45),strength=r[[paste0(state,'_median')]],n=r$n_patients)}};tr<-rbindlist(tri);lab<-unique(tr[,.(partner,direction,state,strength,n)]);lab[,`:=`(x=match(partner,partners)+ifelse(state=='high',-.17,.17),y=ifelse(state=='high',.2,-.2))];lab[,label:=paste0(ifelse(state=='high','H','L'),'\n',formatC(strength,format='g',digits=3))];nn<-unique(lab[,.(partner,direction,n)]);nn[,x:=match(partner,partners)]
p<-ggplot(tr,aes(x,y,group=id,fill=strength))+geom_polygon(color='white',linewidth=.4)+geom_text(data=lab,aes(x,y,label=label,color=ifelse(strength<.45*max(tr$strength,na.rm=TRUE),'white','black')),inherit.aes=FALSE,size=3,family='Arial')+scale_color_identity(guide='none')+geom_text(data=nn,aes(x,.68,label=paste0('n=',n)),inherit.aes=FALSE,size=3,family='Arial')+facet_wrap(~direction,ncol=1)+scale_fill_viridis_c(na.value='grey85',guide=guide_colourbar(display='rectangles'))+scale_x_continuous(breaks=seq_along(partners),labels=nice(partners))+scale_y_continuous(limits=c(-.6,.8),breaks=NULL)+jin_theme()+theme(axis.text.x=element_text(angle=30,hjust=1),axis.line=element_blank(),axis.ticks=element_blank())+labs(x=NULL,y=NULL,fill='Median strength');exp(p,'communication_dual_triangle',tr,12,5.5)
